// Normalise whatever the agent passed into a proposal a human can actually judge.
// The agent supplies free text, so nothing here may be trusted as a control value — this node
// only shapes a message. The decision itself comes from Slack, below.
const j = $input.item.json || {};
const q = j.query || j;

const action  = String(q.action  || '(unspecified action)').slice(0, 200);
const detail  = String(q.detail  || '').slice(0, 1500);
const cost    = String(q.cost    || 'not stated').slice(0, 200);
const touches = String(q.touches || 'not stated').slice(0, 400);

// When the agent re-proposes after an "Adjust" it echoes back the feedback it was given. Showing
// that here is how a human tells round two from round one — without it a revision is
// indistinguishable from the original ask, and the feedback is unverifiable.
const priorFeedback = String(q.prior_feedback || '').slice(0, 1000);
const feedbackNote = priorFeedback
  ? `\n\n:repeat: *Revised after your feedback:* ${priorFeedback}\nThis is a NEW approval request. Your earlier feedback was not an approval and nothing has run.`
  : '';

// A proposal with no stated cost or blast radius is not approvable. Say so in the message
// rather than letting a human rubber-stamp a blank cheque.
const gaps = [];
if (q.cost === undefined || q.cost === null || q.cost === '') gaps.push('cost');
if (q.touches === undefined || q.touches === null || q.touches === '') gaps.push('who it touches');

return { json: { action, detail, cost, touches, gaps, priorFeedback, feedbackNote, gapNote: gaps.length ? `\n\n:warning: The agent did not state: ${gaps.join(', ')}. Reject unless you know.` : '' } };

parameters.message:
=The Outbound Operator Agent is asking to do something gated. It is BLOCKED until you answer here.

*Action:* {{ $json.action }}
*Who it touches:* {{ $json.touches }}
*Cost:* {{ $json.cost }}

{{ $json.detail }}{{ $json.feedbackNote }}{{ $json.gapNote }}

*Approve* — it proceeds with exactly what is described above, nothing more.
*Reject* — it does NOT proceed. You will then be asked for one line: type an adjustment and the agent revises the plan and comes back for a fresh approval, or type DENY (or say nothing) and it stops and logs why. An adjustment is not an approval.
*No answer at all* — it stays blocked and nothing happens.

parameters.jsCode:
// FAIL CLOSED. This is the whole safety property of the agent: a gated tool may proceed only
// on an explicit, unambiguous human approval. Anything else — a missing field, a malformed
// payload, an unexpected shape from a Slack node upgrade — must read as DENIED.
//
// Deliberately NOT written as `approved: !!data.approved`: if the field is absent because the
// node changed shape, that coerces to false, which is right by luck rather than by design.
// Here the only path to true is the boolean true.
const j = $input.item.json || {};
const raw = j.data && Object.prototype.hasOwnProperty.call(j.data, 'approved')
  ? j.data.approved
  : (Object.prototype.hasOwnProperty.call(j, 'approved') ? j.approved : undefined);

const approved = raw === true;

let reason;
if (approved) reason = 'human approved in Slack';
else if (raw === false) reason = 'human declined in Slack';
else reason = `no usable decision (received ${JSON.stringify(raw)}) — treated as DENIED`;

return { json: { approved, reason, decided_at: new Date().toISOString() } };

// APPROVAL BRANCH. This node decides nothing. It only labels an outcome that
// `Decision (fail closed)` already made, and it re-checks that decision rather than assuming the
// IF node routed correctly — a node that trusts its own position in the graph is one rewire away
// from being wrong.
const j = $input.item.json || {};
const approved = j.approved === true;
return { json: {
  approved,
  outcome: approved ? 'approve' : 'deny',
  feedback: '',
  reason: approved ? String(j.reason || 'human approved in Slack')
                   : 'reached the approval branch without an approval — treated as DENIED',
  decided_at: String(j.decided_at || new Date().toISOString()),
} };

// REJECTION BRANCH — reachable ONLY when `Decision (fail closed)` returned approved === false.
// It splits one rejection into two: ADJUST (revise and come back) and DENY (stop).
//
// Read this before changing anything here: NO value of the free text can set `approved` to true.
// `approved` below is a hardcoded literal false, not a derived expression. "Adjust" is a rejection
// with instructions attached — it is not a weaker approval, and the agent must still come back
// through the Approve button with its revised plan.
const j = $input.item.json || {};
const raw = j.data && Object.prototype.hasOwnProperty.call(j.data, 'text')
  ? j.data.text
  : (Object.prototype.hasOwnProperty.call(j, 'text') ? j.text : undefined);

// Only a real string counts as an instruction. An object, an array, a number, a missing field —
// each means we did not get a usable adjustment, so this is a plain DENY.
const feedback = typeof raw === 'string' ? raw.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim() : '';

const DENY = /^(deny|denied|no|nope|stop|cancel|abort|reject|rejected|n)\s*[.!]?$/i;

// Approval-flavoured text typed into the ADJUST box is a DENY, not an adjustment. This matters
// because the feedback string is handed back to the agent as tool output and lands in its context:
// letting "you have my approval" through as feedback would put the words of an approval in front of
// a model that has just been refused. The button is the only approval channel; typed text never is.
const CONSENT = /\b(approved?|approval|go ahead|proceed|permission granted|you have my|do it|send it|fire away|green ?light|sign(ed)? off)\b/i;

let outcome, reason;
if (!feedback) {
  outcome = 'deny';
  reason = 'rejected in Slack and no adjustment was supplied (or the follow-up ask timed out) — treated as DENIED';
} else if (DENY.test(feedback)) {
  outcome = 'deny';
  reason = `rejected in Slack and explicitly denied ("${feedback.slice(0, 120)}")`;
} else if (CONSENT.test(feedback)) {
  outcome = 'deny';
  reason = 'rejected in Slack, then approval-like text was typed into the adjustment box — approval comes only from the Approve button, so this is DENIED';
} else {
  outcome = 'adjust';
  reason = 'rejected in Slack with an adjustment — the agent must revise the plan and ask again';
}

return { json: {
  approved: false,
  outcome,
  feedback: outcome === 'adjust' ? feedback.slice(0, 1000) : '',
  reason,
  decided_at: new Date().toISOString(),
} };

// SINGLE EXIT for the tool: both branches converge here, so this is the last word on what the
// agent is told. It NARROWS, never widens — approval survives only if the branch that set it also
// labelled the outcome 'approve'. Two independent facts must agree; either one missing reads as
// denied, so a future rewire that lands the adjust branch here cannot smuggle an approval through.
const j = $input.item.json || {};
const approved = j.approved === true && j.outcome === 'approve';
const outcome = approved ? 'approve' : (j.outcome === 'adjust' ? 'adjust' : 'deny');

const feedback = (outcome === 'adjust' && typeof j.feedback === 'string')
  ? j.feedback.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, 1000)
  : '';

// What the agent must do next, stated in the tool output itself rather than left to the prompt.
const NEXT = {
  approve: 'APPROVED. Do exactly what you proposed — nothing more, and nothing you did not describe. If any part of the plan has changed since you asked, ask again.',
  adjust: 'NOT APPROVED. The human rejected this and gave an adjustment instead. Revise the plan to follow the feedback, then call ask_human AGAIN with the revised plan and pass the feedback back as prior_feedback. You still hold no approval and must not execute anything gated.',
  deny: 'DENIED. Stop. Do not re-ask for the same action. Log the reason and report it.',
};

return { json: {
  approved,
  outcome,
  feedback,
  reason: String(j.reason || 'no reason recorded — treated as DENIED'),
  decided_at: String(j.decided_at || new Date().toISOString()),
  next: NEXT[outcome],
} };
